import XCTest
@testable import SnarwalCore

let sampleGCode = """
; generated by OrcaSlicer Snarwal-Kiri:Moto on 2026-10-19 20:00:00
PRINT_START
M83
G1 X10 Y10 F9000
;BEFORE_LAYER_CHANGE
;0.2
G92 E0
G1 X20 Y10 E1.2
G1 X20 Y20 E1.2
G1 X30 Y30 F9000
T1
G1 X40 Y30 E0.5 ; wall
G1 E-0.8
;BEFORE_LAYER_CHANGE
;0.4
G1 X50 Y30 E0.5
PRINT_END
; estimated printing time (normal mode) = 1h 2m 3s
; total layers count = 2
; filament used [mm] = 10.00,5.00,0.00,0.00
; filament used [g] = 1.50,0.75,0.00,0.00
"""

final class SlicingTests: XCTestCase {
    func testPreviewSplitsLayersAndTools() throws {
        let preview = GCodePreview(gcode: sampleGCode)
        XCTAssertEqual(preview.layers.count, 2)
        XCTAssertEqual(preview.layers[0].z, 0.2)
        XCTAssertEqual(preview.layers[0].segments[0], [10, 10, 20, 10, 20, 10, 20, 20])
        XCTAssertEqual(preview.layers[0].segments[1], [30, 30, 40, 30])
        XCTAssertEqual(preview.layers[1].z, 0.4)
        XCTAssertEqual(preview.layers[1].segments[1], [40, 30, 50, 30])
        let b = try XCTUnwrap(preview.bounds)
        XCTAssertEqual([b.minX, b.minY, b.maxX, b.maxY], [10, 10, 50, 30])
    }

    func testSummaryFromFooter() throws {
        let summary = try XCTUnwrap(GCodeSummary(gcode: sampleGCode))
        XCTAssertEqual(summary.printTime, 3723)
        XCTAssertEqual(summary.layers, 2)
        XCTAssertEqual(summary.gramsPerTool, [1.5, 0.75, 0, 0])
        XCTAssertEqual(summary.totalGrams, 2.25, accuracy: 1e-9)
    }

    func testKiriProcessFromSettings() {
        let settings = SliceSettings(quality: .fine, infill: 30, supports: true, brim: true)
        let petg = HeadFilament(tool: 2, material: .petg)
        let process = settings.kiriProcess(firstHead: petg)
        XCTAssertEqual(process["sliceHeight"], .number(0.12))
        XCTAssertEqual(process["sliceFillSparse"], .number(0.3))
        XCTAssertEqual(process["sliceSupportType"], .string("automatic"))
        XCTAssertEqual(process["outputBrimCount"], .number(5))
        XCTAssertEqual(process["outputTemp"], .number(245))
        XCTAssertEqual(process["outputBedTemp"], .number(75))
        // PETG flow limit 12 mm³/s at 0.12 × 0.45 mm caps the speed below the fine preset
        if case .number(let feed) = process["outputFeedrate"] {
            XCTAssertLessThanOrEqual(feed * 0.12 * 0.45, 12.0001)
        } else {
            XCTFail("feedrate missing")
        }
        XCTAssertEqual(SliceSettings().kiriProcess(firstHead: HeadFilament(tool: 0))["sliceSupportType"], .string("disabled"))
    }

    func testMaterialFromPrinterType() {
        XCTAssertEqual(Material(printerType: "PLA"), .pla)
        XCTAssertEqual(Material(printerType: "petg hf"), .petg)
        XCTAssertEqual(Material(printerType: "PLA-CF"), .pla)
        XCTAssertNil(Material(printerType: "NONE"))
        XCTAssertNil(Material(printerType: "PA6"))
    }
}
